def escape(s):
    return s.replace("\\", "\\\\").replace('"', '\\"').replace("\n", "\\n")


if __name__ == "__main__":
    root = os.path.join(os.path.dirname(__file__), "..", "Resources")
    for i, lang in enumerate(["it", "fr"]):
        folder = os.path.join(root, lang + ".lproj")
        os.makedirs(folder, exist_ok=True)
        with open(os.path.join(folder, "Localizable.strings"), "w", encoding="utf-8") as f:
            for key in sorted(T):
                f.write(f'"{escape(key)}" = "{escape(T[key][i])}";\n')
    print(f"Wrote {len(T)} strings for it and fr")
